    hrows={r for r,cs in byrow.items() if len(cs)>=2}
    vcols={c for cs in bycol.values() if len(cs)>=2}
    frs=set(); fys=set()
    # choose one orientation if both exist? In demo1 only hrows. Try: use the orientation with more lines, or both?
    def beam(p,dr,dc):
        rr,cc=p
        while True:
            rr+=dr; cc+=dc
            if not(0<=rr<H and 0<=cc<W): break
            v=out[rr][cc]
            if v!=0: break
            out[rr][cc]=3
    used={}
    assigned=[False]*len(pts)
    def mark(k):
        for i,kv in enumerate(list(byrow.keys())+list(bycol.keys())): pass
    for idx,p in enumerate(pts):
        r,c=p
        assigned[idx]=False
    # decide orientation: pick cells with >=2 aligned neighbors? each point may belong to exactly one segment line or none.
    seg_cells=set()
    for r in hrows:
        cs=sorted(byrow[r]); lo,hi=cs[0],cs[-1]
        if any(seg_cells & {(r,c) for c in range(lo,hi+1)}): continue
        for c in range(lo,hi+1): seg_cells.add((r,c))
    for c in vcols:
        rs=sorted(bycol[c]); lo,hi=rs[0],rs[-1]
        if seg_cells & {(r,c) for r in range(lo,hi+1)}: continue
        for r in range(lo,hi+1): seg_cells.add((r,c))
    usedp={(r,c) for r,c in seg_cells}
    for dr,dc in ((0,1),(0,-1),(1,0),(-1,0)):
