                byrow.setdefault(r,[]).append(c); bycol.setdefault(c,[]).append(r)
    pts=[(r,c) for r in range(H) for c in range(W) if grid[r][c]==2]
    def fill(k,lo,hi):
        for i in range(lo,hi+1):
            if out[k][i]!=2: out[k][i]=3
    if any(len(cs)>=2 for cs in byrow.values()):
        k=max([kk for kk,cs in byrow.items() if len(cs)>=2], key=lambda kk:max(byrow[kk]))
        # choose bar = row with most spread / any; pick first
        k=next((kk for kk,cs in sorted(byrow.items()) if len(cs)>=2),0)
        gg=sorted(byrow[k])
        lo,hi=gg[0],gg[-1]
        fill(k,lo,hi)
        for r,c in pts:
            if r==k: continue
            rng=list(range(r+1,k)) if r<k else list(range(k,r))
            for rr in rng: out[rr][c]=3
    elif any(len(rs)>=2 for rs in bycol.values()):
        k=next((kk for kk,rs in sorted(bycol.items()) if len(rs)>=2),0)
        gg=sorted(bycol[k])
        fill(None,0,0)
        lo,hi=gg[0],gg[-1]
        for i in range(lo,hi+1):
            if out[i][k]!=2: out[i][k]=3
        for r,c in pts:
            if c==k: continue
            rng=list(range(c+1,k)) if c<k else list(range(k,c))
            for cc in rng: out[r][cc]=3
    return out

